// Generated by AI (UnitTest MCP)
//! Structural guard: every Bridge static page must wire up to the single
//! shared chrome source (`static/shared/chrome.css` + `chrome.js`) instead
//! of inlining its own copy, so a user on any one page can always reach
//! every other and a new capability is declared in exactly one place
//! (ADR-0124). Pages are discovered from the `static/` directory at test
//! run time (not a hand-maintained list), so a new page can never silently
//! slip through unchecked -- that gap is exactly what let
//! `administration.html` and `supervisors.html` land with their own,
//! already-diverging nav before this guard first shipped, and what let
//! every page duplicate the same brand/nav markup, CSS, and disclosure
//! script a second time after that.

use std::fs;
use std::path::Path;

const EVIDENCE: &str = include_str!("../static/evidence.html");
const CHROME_JS: &str = include_str!("../static/shared/chrome.js");

/// Every `.html` file under `static/`, sorted for a deterministic order.
fn discover_pages() -> Vec<(String, String)> {
    let static_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("static");
    let mut pages: Vec<(String, String)> = fs::read_dir(&static_dir)
        .unwrap_or_else(|error| panic!("reading {}: {error}", static_dir.display()))
        .filter_map(|entry| entry.ok())
        .filter(|entry| {
            entry
                .path()
                .extension()
                .is_some_and(|extension| extension == "html")
        })
        .map(|entry| {
            let file_name = entry.file_name().to_string_lossy().into_owned();
            let content = fs::read_to_string(entry.path())
                .unwrap_or_else(|error| panic!("reading {file_name}: {error}"));
            (file_name, content)
        })
        .collect();
    pages.sort_by(|a, b| a.0.cmp(&b.0));
    assert!(
        !pages.is_empty(),
        "no .html pages found under {}",
        static_dir.display()
    );
    pages
}

/// The static-file stem is also the id every page must declare in
/// `data-current`, and the id `chrome.js`'s `NAV_ITEMS` uses for that same
/// capability -- `index.html` is no exception, since `chrome.js`'s Fleet
/// entry is itself declared with `id: "index"`.
fn current_id(file_name: &str) -> String {
    file_name.trim_end_matches(".html").to_string()
}

/// The full capability id set from ADR-0105 decision 5's Bridge navigation
/// surface (task:60ba293846ec), now declared exactly once in `chrome.js`'s
/// `NAV_ITEMS`. Ids not yet backed by a real page in `static/` stay
/// disabled placeholders (`href: null`) until their own page lands.
const CAPABILITY_IDS: &[&str] = &[
    "index",
    "graph",
    "agents",
    "evidence",
    "telemetry",
    "context",
    "work",
    "board-doctor",
    "design",
    "constitution",
    "knowledge",
    "administration",
    "supervisors",
    "delegations",
    "live-feed",
];

/// The text of a single `NAV_ITEMS` entry (or nested group item), from its
/// `id: "..."` up to (not including) the closing `}` -- enough to inspect
/// its `href` without needing a real JS/JSON parser for one test file.
fn nav_item_segment<'a>(chrome_js: &'a str, id: &str) -> &'a str {
    let needle = format!(r#"id: "{id}""#);
    let start = chrome_js
        .find(&needle)
        .unwrap_or_else(|| panic!("chrome.js has no NAV_ITEMS entry with id \"{id}\""));
    let end = chrome_js[start..]
        .find('}')
        .map(|offset| start + offset)
        .unwrap_or_else(|| panic!("chrome.js's \"{id}\" entry is never closed"));
    &chrome_js[start..end]
}

#[test]
fn every_bridge_page_loads_the_shared_chrome_assets() {
    let pages = discover_pages();
    for (name, html) in &pages {
        assert!(
            html.contains(r#"<link rel="stylesheet" href="/static/shared/chrome.css">"#),
            "{name} must link the shared /static/shared/chrome.css instead of inlining its own \
             brand/nav CSS"
        );
        assert!(
            html.contains(r#"<script src="/static/shared/chrome.js" defer></script>"#),
            "{name} must load the shared /static/shared/chrome.js instead of inlining its own \
             disclosure script"
        );
    }
}

#[test]
fn every_bridge_page_declares_brand_and_nav_mount_points() {
    let pages = discover_pages();
    for (name, html) in &pages {
        assert!(
            html.contains("data-bridge-brand"),
            "{name} is missing the [data-bridge-brand] mount point chrome.js renders into"
        );
        assert!(
            html.contains("data-bridge-nav"),
            "{name} is missing the [data-bridge-nav] mount point chrome.js renders into"
        );
    }
}

#[test]
fn every_bridge_page_declares_its_own_current_capability() {
    let pages = discover_pages();
    for (name, html) in &pages {
        let expected_current = current_id(name);
        let needle = format!(r#"data-current="{expected_current}""#);
        assert!(
            html.contains(&needle),
            "{name} must declare {needle} on its [data-bridge-nav] mount so chrome.js \
             highlights the right entry"
        );
    }
}

#[test]
fn every_bridge_page_bridges_the_neutral_chrome_tokens() {
    // chrome.css only ever reads --chrome-*; a page that forgets to map its
    // own palette onto these renders the shared nav and brand unstyled.
    let pages = discover_pages();
    for (name, html) in &pages {
        for token in [
            "--chrome-surface:",
            "--chrome-line:",
            "--chrome-ink:",
            "--chrome-muted:",
            "--chrome-accent:",
            "--chrome-focus:",
        ] {
            assert!(
                html.contains(token),
                "{name} must bridge {token} onto its own palette for chrome.css to pick up"
            );
        }
    }
}

#[test]
fn chrome_js_declares_every_known_capability_id() {
    for id in CAPABILITY_IDS {
        nav_item_segment(CHROME_JS, id);
    }
}

#[test]
fn every_page_that_exists_has_a_real_entry_in_chrome_js() {
    let pages = discover_pages();
    for (file_name, _) in &pages {
        let id = current_id(file_name);
        let segment = nav_item_segment(CHROME_JS, &id);
        assert!(
            !segment.contains("href: null"),
            "{file_name} exists under static/ but chrome.js's \"{id}\" NAV_ITEMS entry is still \
             a disabled placeholder (href: null) -- give it a real href now that the page ships"
        );
    }
}

#[test]
fn every_disabled_capability_in_chrome_js_has_no_backing_page() {
    // A disabled nav entry with no href is not keyboard-focusable and is not
    // announced as a link by assistive tech, and it must stay disabled only
    // for as long as no real page exists behind it.
    for id in CAPABILITY_IDS {
        let segment = nav_item_segment(CHROME_JS, id);
        if !segment.contains("href: null") {
            continue;
        }
        let page_path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("static")
            .join(format!("{id}.html"));
        assert!(
            !page_path.exists(),
            "chrome.js's \"{id}\" entry is a disabled placeholder but static/{id}.html now \
             exists -- give it a real href"
        );
    }
}

#[test]
fn evidence_related_record_links_remain_separate_from_navigation() {
    // Evidence's own "#api-links" related-records section (a per-repository
    // raw-API deep link, labelled "Related Industrial records") is a
    // different feature from the shared page nav above and must stay that
    // way -- it must never be reintroduced by reusing the nav's own ids.
    for id in ["work-api", "constitution-api", "knowledge-api"] {
        assert!(
            EVIDENCE.contains(&format!("id=\"{id}\"")),
            "Evidence must retain its related-record link {id}"
        );
    }
    for removed_navigation_id in ["work-link", "constitution-link", "knowledge-link"] {
        assert!(
            !EVIDENCE.contains(&format!("id=\"{removed_navigation_id}\"")),
            "Evidence navigation must not rewire a capability placeholder through raw API links"
        );
    }
}
